export function yearChange(data,freq){const map=new Map(data);return data.flatMap(([d,v],i)=>{const target=(+d.slice(0,4)-1)+d.slice(4);let base=map.get(target);if(base===undefined&&(freq==='D'||freq==='W')){const t=Date.parse(target);let lo=0,hi=i-1;while(lo<=hi){const m=(lo+hi)>>1;if(data[m][0]<=target)lo=m+1;else hi=m-1}if(hi>=0&&t-Date.parse(data[hi][0])<=864e5*(freq==='D'?10:14))base=data[hi][1]}return base===undefined||base===0?[]:[[d,(v/base-1)*100]]})}
export function ratio(a,b){const m=new Map(b);return a.flatMap(([d,v])=>m.has(d)&&m.get(d)!==0?[[d,v/m.get(d)*100]]:[])}
export function transform(s,mode,start,end){let data=mode==='yoy'?yearChange(s.data,s.freq):s.data;data=data.filter(([d])=>d>=start&&d<=end);if(mode==='index'){if(!data.length||data[0][1]<=0)return [];const first=data[0][1];data=data.map(([d,v])=>[d,v/first*100])}return data}
export function nearest(data,date){if(!data.length)return null;let a=0,b=data.length-1;while(a<b){const m=(a+b)>>1;if(data[m][0]<date)a=m+1;else b=m}return a>0&&Math.abs(Date.parse(data[a-1][0])-Date.parse(date))<Math.abs(Date.parse(data[a][0])-Date.parse(date))?data[a-1]:data[a]}
